28	/**
29	 * The ManageFishingSpotFragment is used to add and edit fishing spots. This
30	 * {@link ManageContentFragment} subclass works slightly different than others. It doesn't interact
31	 * with the backend database directly. This is so {@link FishingSpot} objects aren't manipulated in
32	 * the database before the user saves the location.
33	 *
34	 * @author Cohen Adair
35	 */
36	public class ManageFishingSpotFragment extends ManageContentFragment {
37	
38	    private InputTextView mNameView;
39	    private InputTextView mLatitudeView;
40	    private InputTextView mLongitudeView;
