42	    private ImageView mCrosshairs;
43	    private GoogleMap mMap;
44	
45	    private List<UserDefineObject> mFishingSpots;
46	    private ManageObjectSpec mManageObjectSpec;
47	    private InitializeInterface mInitializeInterface;
48	    private OnVerifyInterface mOnVerifyInterface;
49	
50	    // if we're adding a fishing spot to a location that already has spots, we want to zoom to the
51	    // other spots for user convenience
52	    private boolean mStopLocationUpdates;
53	
54	    /**
55	     * Used to verify the new fishing spot being added is unique to the location.
56	     */
57	    public interface OnVerifyInterface {
58	        boolean isDuplicate(FishingSpot fishingSpot);
59	    }
