103	    }
104	
105	    public void setManageObjectSpec(ManageObjectSpec manageObjectSpec) {
106	        mManageObjectSpec = manageObjectSpec;
107	    }
108	
109	    public void setInitializeInterface(InitializeInterface initializeInterface) {
110	        mInitializeInterface = initializeInterface;
