122	    @Override
123	    public boolean verifyUserInput() {
124	        FishingSpot fishingSpot = getNewFishingSpot();
125	        fishingSpot.setName(mNameView.getInputText());
126	
127	        if (mMap != null) {
128	            fishingSpot.setLatitude(mMap.getCameraPosition().target.latitude);
129	            fishingSpot.setLongitude(mMap.getCameraPosition().target.longitude);
130	        } else {
131	            // in case Google Play Services isn't available, fishing spots can still be added and updated later
132	            fishingSpot.setLatitude(0.0);
133	            fishingSpot.setLongitude(0.0);
134	        }
135	
136	        // name
137	        if (fishingSpot.isNameNull()) {
138	            AlertUtils.showError(getActivity(), R.string.error_name);
139	            return false;
140	        }
141	
142	        // duplicate name
143	        if (!isEditing() && mOnVerifyInterface.isDuplicate(fishingSpot)) {
144	            AlertUtils.showError(getActivity(), R.string.error_fishing_spot_name);
145	            return false;
146	        }
147	
148	        return true;
