157	    private void updateMap() {
158	        if (mMap == null)
159	            return;
160	
161	        updateCrosshairs(mMap.getMapType());
162	
163	        // move the camera to the current fishing spot
164	        if (isEditing()) {
165	            mStopLocationUpdates = true;
166	            updateCamera(getNewFishingSpot().getCoordinates());
167	        } else if (mFishingSpots != null) {
168	            // if the location already has fishing spots, move the camera to one
169	            // this is simply for user convenience
170	            if (mFishingSpots.size() > 0) {
171	                mStopLocationUpdates = true;
172	                updateCamera(((FishingSpot)mFishingSpots.get(0)).getCoordinates());
173	            }
174	        }
