177	    /**
178	     * Adds an icon to the toolbar that allows users to change the map type.
179	     */
180	    private void initToolbar() {
181	        // find the toolbar layout
182	        LinearLayout toolbar = null;
183	
184	        View parent = getParentFragment().getView();
185	        if (parent != null)
186	            toolbar = (LinearLayout)parent.findViewById(R.id.toolbar_view);
187	
188	        // create the icon
189	        ImageButton mapType = new ImageButton(getContext());
190	
191	        mapType.setImageResource(R.drawable.ic_map);
192	        mapType.setBackgroundResource(Utils.resIdFromAttr(getContext(), android.R.attr.selectableItemBackground));
193	        mapType.setContentDescription(getResources().getString(R.string.select_map_type));
194	        mapType.setColorFilter(Color.BLACK);
195	        mapType.setOnClickListener(new View.OnClickListener() {
196	            @Override
197	            public void onClick(View v) {
198	                mMapFragment.onClickMapTypeOption(true);
199	            }
