201	
202	        LinearLayout.LayoutParams params = new LinearLayout.LayoutParams(
203	                getResources().getDimensionPixelOffset(R.dimen.image_button_size),
204	                getResources().getDimensionPixelOffset(R.dimen.image_button_size)
