206	
207	        params.setMargins(
208	                0,
209	                getResources().getDimensionPixelOffset(R.dimen.margin_default),
210	                getResources().getDimensionPixelOffset(R.dimen.margin_default),
211	                getResources().getDimensionPixelOffset(R.dimen.margin_default)
212	        );
213	
214	        mapType.setLayoutParams(params);
215	
216	        // add the icon
217	        if (toolbar != null)
218	            toolbar.addView(mapType);
