225	    private void initCoordinatesView(View view) {
226	        mLatitudeView = (InputTextView)view.findViewById(R.id.latitude_layout);
227	        mLatitudeView.setAllowsNegativeNumbers(true);
228	
229	        mLongitudeView = (InputTextView)view.findViewById(R.id.longitude_layout);
