233	    private void initRefreshButton(View view) {
234	        ImageButton refreshButton = (ImageButton)view.findViewById(R.id.coordinate_refresh_button);
235	        refreshButton.setOnClickListener(new View.OnClickListener() {
236	            @Override
237	            public void onClick(View v) {
238	                if (mLatitudeView.getInputText() == null || mLongitudeView.getInputText() == null)
239	                    return;
240	
241	                double lat = validateCoordinateInput(mLatitudeView);
242	                double lng = validateCoordinateInput(mLongitudeView);
243	
244	                if (lat != -1 && lng != -1) {
245	                    LatLng latLng = new LatLng(lat, lng);
246	
247	                    if (mMapFragment.isValid(latLng)) {
248	                        mMapFragment.updateCameraNoZoom(latLng);
249	                    }
250	                }
251	            }
252	        });
253	    }
254	
255	    private void updateCoordinateViews(LatLng coordinates) {
256	        mLatitudeView.setInputText(String.format(getResources().getConfiguration().locale, "%.6f", coordinates.latitude));
257	        mLongitudeView.setInputText(String.format(getResources().getConfiguration().locale, "%.6f", coordinates.longitude));
258	    }
259	
260	    /**
261	     * Validates the given {@link InputTextView}. If the input is invalid a Toast will be displayed
262	     * to the user and the previously entered character will be removed.
263	     *
264	     * @param input The {@link InputTextView} to validate.
265	     * @return The text of the input as a double.
266	     */
267	    private double validateCoordinateInput(InputTextView input) {
268	        String inputText = input.getInputText();
269	
270	        // do not validate if the user is entering a negative coordinate
271	        if (inputText.length() == 1 && inputText.charAt(0) == '-')
272	            return -1;
273	
274	        try {
275	            inputText = inputText.replace(',', '.'); // some countries/keyboard use ',' in place of '.'
276	            return (double) Utils.asFloat(inputText, 0);
277	        } catch (NumberFormatException e) {
278	            e.printStackTrace();
279	            Utils.showToast(getContext(), R.string.msg_invalid_coordinate);
280	            input.pressBackspace();
281	        }
282	
283	        return -1;
284	    }
285	
286	    private void initMapFragment() {
287	        mMapFragment = (DraggableMapFragment)getChildFragmentManager().findFragmentById(R.id.fishing_spot_map);
288	
289	        mMapFragment.setLocationEnabled(true);
290	        mMapFragment.setLocationUpdatesEnabled(true);
291	        mMapFragment.setHasOptionsMenu(false);
292	
293	        mMapFragment.getMapAsync(new DraggableMapFragment.InteractionListener() {
294	            @Override
295	            public void onMapReady(GoogleMap map) {
296	                mMap = map;
297	                updateMap();
298	            }
299	
300	            @Override
301	            public void onLocationUpdate(android.location.Location location) {
302	                if (mStopLocationUpdates) {
303	                    mMapFragment.setLocationUpdatesEnabled(false);
304	                    return;
305	                }
306	
307	                updateCamera(new LatLng(location.getLatitude(), location.getLongitude()));
308	                mMapFragment.setLocationUpdatesEnabled(false);
309	            }
310	        });
311	
312	        mMapFragment.setOnDragListener(new GoogleMapLayout.OnDragListener() {
313	            @Override
314	            public void onDrag(MotionEvent motionEvent) {
315	                if (mMap != null)
316	                    updateCoordinateViews(mMap.getCameraPosition().target);
317	            }
318	        });
319	
320	        mMapFragment.setOnUpdateMapType(new DraggableMapFragment.OnUpdateMapType() {
321	            @Override
322	            public void onUpdate(int mapType) {
323	                updateCrosshairs(mapType);
324	            }
325	        });
326	
327	        updateCoordinateViews(new LatLng(0.0, 0.0));
328	    }
329	
330	    private void updateCamera(LatLng loc) {
331	        mMapFragment.updateCamera(loc);
332	        updateCoordinateViews(loc);
333	    }
334	
335	    /**
336	     * Changes the color of the center crosshairs depending on the given map type.
337	     * @param mapType The type of the map.
338	     */
339	    private void updateCrosshairs(int mapType) {
340	        boolean isDark = mapType == GoogleMap.MAP_TYPE_SATELLITE || mapType == GoogleMap.MAP_TYPE_HYBRID;
341	        mCrosshairs.setColorFilter(isDark ? Color.WHITE : Color.BLACK);
342	    }
343	}
