27	/**
28	 * The ManageLocationFragment is used to add and edit locations.
29	 */
30	public class ManageLocationFragment extends ManageContentFragment {
31	
32	    private LinearLayout mContainer;
33	    private InputTextView mNameView;
34	
35	    private ArrayList<MoreDetailView> mFishingSpotViews;
36	    private ArrayList<UserDefineObject> mFishingSpots;
37	
38	    public ManageLocationFragment() {
39	        // Required empty public constructor
40	    }
41	
42	    private Location getNewLocation() {
43	        return (Location)getNewObject();
44	    }
45	
46	    @Override
47	    public View onCreateView(LayoutInflater inflater, ViewGroup container, Bundle savedInstanceState) {
48	        View view = inflater.inflate(R.layout.fragment_manage_location, container, false);
49	
50	        mContainer = (LinearLayout)view.findViewById(R.id.container);
51	
52	        initNameView(view);
53	        initAddFishingSpotView(view);
54	        initSubclassObject();
55	
56	        if (mFishingSpots == null || !isEditing())
57	            mFishingSpots = new ArrayList<>();
58	
59	        if (mFishingSpotViews == null)
60	            mFishingSpotViews = new ArrayList<>();
61	
62	        return view;
63	    }
64	
65	    @Override
66	    public void onResume() {
67	        super.onResume();
68	        mNameView.addOnInputTextChangedListener(ViewUtils.onTextChangedListener(new ViewUtils.OnTextChangedListener() {
69	            @Override
70	            public void onTextChanged(String newText) {
