170	    private void initAddFishingSpotView(View view) {
171	        InputButtonView addFishingSpotView = (InputButtonView)view.findViewById(R.id.add_fishing_spot_view);
172	        addFishingSpotView.setOnClickPrimaryButton(new View.OnClickListener() {
173	            @Override
174	            public void onClick(View v) {
175	                goToManageFishingSpot(null);
