180	    private void addFishingSpot(final FishingSpot spot) {
181	        final MoreDetailView fishingSpotView = new MoreDetailView(getContext());
182	        fishingSpotView.setTitle(spot.getName());
183	        fishingSpotView.setSubtitle(spot.getCoordinatesAsString());
184	        fishingSpotView.setDetailButtonImage(R.drawable.ic_remove);
185	        fishingSpotView.setTitleStyle(R.style.TextView_Small);
186	        fishingSpotView.setSubtitleStyle(R.style.TextView_SmallSubtitle);
187	        fishingSpotView.useNoLeftSpacing();
188	        fishingSpotView.useDefaultStyle();
189	
190	        fishingSpotView.setOnClickDetailButton(new View.OnClickListener() {
191	            @Override
192	            public void onClick(View v) {
193	                mFishingSpots.remove(spot);
194	                mContainer.removeView(fishingSpotView);
195	            }
196	        });
197	
198	        fishingSpotView.setOnClickContent(new View.OnClickListener() {
199	            @Override
200	            public void onClick(View v) {
201	                goToManageFishingSpot(spot.getId());
