209	    /**
210	     * Opens a ManageFishingSpotFragment dialog.
211	     * @param editingId The editing id of the fishing spot, or null if a new spot is being added.
212	     */
213	    private void goToManageFishingSpot(UUID editingId) {
214	        final ManageFishingSpotFragment fragment = new ManageFishingSpotFragment();
215	
216	        if (editingId != null)
217	            fragment.setIsEditing(true, editingId);
218	
219	        // get all possible fishing spots to be used when adding a new spot
220	        // this is purely for user convenience
221	        List<UserDefineObject> allPossibleFishingSpots = mFishingSpots;
222	        mFishingSpots.addAll(getNewLocation().getFishingSpots());
223	        fragment.setFishingSpots(allPossibleFishingSpots);
224	
225	        fragment.setOnVerifyInterface(new ManageFishingSpotFragment.OnVerifyInterface() {
226	            @Override
227	            public boolean isDuplicate(FishingSpot fishingSpot) {
228	                for (UserDefineObject obj : mFishingSpots)
229	                    if (obj.getName().equals(fishingSpot.getName()))
230	                        return true;
231	
232	                return false;
233	            }
234	        });
235	
236	        fragment.setManageObjectSpec(new ManageObjectSpec(R.string.error_fishing_spot_add, R.string.success_fishing_spot_add, R.string.error_fishing_spot_edit, R.string.success_fishing_spot_edit, new ManageInterface() {
237	            @Override
238	            public boolean onEdit() {
239	                for (int i = 0; i < mFishingSpots.size(); i++)
240	                    // update the fishing spot if this is the one we're editing
241	                    if (mFishingSpots.get(i).getId().equals(fragment.getNewFishingSpot().getId())) {
242	                        mFishingSpots.set(i, new FishingSpot(fragment.getNewFishingSpot(), true));
243	                        updateViews();
244	                        return true;
245	                    }
246	
247	                return false;
248	            }
249	
250	            @Override
251	            public boolean onAdd() {
252	                mFishingSpots.add(fragment.getNewFishingSpot());
253	                addFishingSpot(fragment.getNewFishingSpot());
254	                return true;
255	            }
256	        }));
257	
258	        fragment.setInitializeInterface(new InitializeInterface() {
259	            @Override
260	            public UserDefineObject onGetOldObject() {
261	                return getFishingSpot(fragment.getEditingId());
262	            }
263	
264	            @Override
265	            public UserDefineObject onGetNewEditObject(UserDefineObject oldObject) {
266	                return new FishingSpot((FishingSpot) oldObject, true);
267	            }
268	
269	            @Override
270	            public UserDefineObject onGetNewBlankObject() {
271	                return new FishingSpot();
272	            }
273	        });
274	
275	        ManageFragment manageFragment = new ManageFragment();
276	        manageFragment.setTitle(R.string.empty);
277	        manageFragment.setContentFragment(fragment);
278	        manageFragment.show(getChildFragmentManager(), null);
279	    }
280	
281	    @Nullable
282	    private FishingSpot getFishingSpot(UUID id) {
283	        for (UserDefineObject fishingSpot : mFishingSpots)
284	            if (fishingSpot.getId().equals(id))
285	                return (FishingSpot)fishingSpot;
286	
287	        return null;
288	    }
289	
290	}
